package com.fethica.playbackkit.sample.fixtures

/**
 * The audio the sample plays, generated by [TonePattern]: no recording and no third-party
 * audio, so it falls under this repository's own licence.
 *
 * | Name | Path | Kind | Pattern (per second) | Size | SHA-256 |
 * | --- | --- | --- | --- | --- | --- |
 * | tone-30s | /finite/tone-30s.wav | finite, 30 s | 523 Hz for 250 ms | 480,044 bytes | 79c2f778c1cf5b9a9bd9c0c57aa92647b21fd178ac3ccebb570c29645a235191 |
 * | live-a | /live/live-a.wav | live-like, endless | 440 Hz for 150 ms | unbounded | one-second loop d9339178b0a774084d09af503cd8ec5bc7190f82489513cbcb5a2c7e02a8d531 |
 * | live-b | /live/live-b.wav | live-like, endless | 660 Hz for 150 ms | unbounded | one-second loop a7112610b98be2fad18826e5066e50669a595cc4b6e0c2ccd3774fa97f134001 |
 *
 * Each live stream is also served at a mirror path (`/live/live-a-mirror.wav`, ...) with the
 * same bytes and its own scenario, so a failing stream can be retried on a source that
 * works. A unit test regenerates everything and fails if a hash moves, so a generator
 * change must update this table in the same commit.
 */
public object FixtureCatalog {

    public val finite: FiniteTone = FiniteTone("tone-30s", TonePattern(toneHz = 523, toneMillis = 250), seconds = 30)

    public val liveA: LiveTone = LiveTone("live-a", TonePattern(toneHz = 440, toneMillis = 150))

    public val liveB: LiveTone = LiveTone("live-b", TonePattern(toneHz = 660, toneMillis = 150))

    public val live: List<LiveTone> = listOf(liveA, liveB)

    /** The mirror path of [tone]: same bytes, separate scenario. */
    public fun mirrorPath(tone: LiveTone): String = "/live/${tone.name}-mirror.wav"

    public const val FINITE_SHA256: String = "79c2f778c1cf5b9a9bd9c0c57aa92647b21fd178ac3ccebb570c29645a235191"

    /** SHA-256 of each live stream's one-second loop, by name. */
    public val LOOP_SHA256: Map<String, String> = mapOf(
        "live-a" to "d9339178b0a774084d09af503cd8ec5bc7190f82489513cbcb5a2c7e02a8d531",
        "live-b" to "a7112610b98be2fad18826e5066e50669a595cc4b6e0c2ccd3774fa97f134001",
    )
}
